# كل صف مرتبط فقط بموضوع «بنك الأسئلة» المحدد له.
CLASS_TOPICS = {
    (-1003062601820, 201): "4e",
    (-1003257155206, 224): "5e",
    (-1003232581205, 218): "6e",
    (-1003221185811, 357): "1m",
    (-1003234532831, 333): "2m",
    (-1003283563361, 192): "3m",
}

def location_grade(update):
    chat = update.effective_chat
    if not chat:
        return None
    # في الخاص يبقى البنك الكامل متاحًا.
    if chat.type == "private":
        return "private"
    message = update.effective_message
    thread_id = getattr(message, "message_thread_id", None) if message else None
    return CLASS_TOPICS.get((chat.id, thread_id))

def allowed_callback_grade(update):
    q = update.callback_query
    if not q or not q.message:
        return None
    chat = q.message.chat
    if chat.type == "private":
        return "private"
    return CLASS_TOPICS.get((chat.id, getattr(q.message, "message_thread_id", None)))


def grade_keyboard():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("خامس ابتدائي", callback_data="grade|5e"), InlineKeyboardButton("رابع ابتدائي", callback_data="grade|4e")],
        [InlineKeyboardButton("أول متوسط", callback_data="grade|1m"), InlineKeyboardButton("سادس ابتدائي", callback_data="grade|6e")],
        [InlineKeyboardButton("ثالث متوسط", callback_data="grade|3m"), InlineKeyboardButton("ثاني متوسط", callback_data="grade|2m")],
    ])

def lesson_keyboard(code):
    _, units = CURRICULUM[code]
    rows=[]
    for ui,(unit,lessons) in enumerate(units):
        rows.append([InlineKeyboardButton(f"📘 {unit}", callback_data="noop")])
        for li,lesson in enumerate(lessons):
            rows.append([InlineKeyboardButton(f"🔹 {lesson}", callback_data=f"lesson|{code}|{ui}|{li}")])
    rows.append([InlineKeyboardButton("↩️ تغيير الصف", callback_data="home")])
    return InlineKeyboardMarkup(rows)

def after_keyboard(code):
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("📚 نعم، درس آخر", callback_data=f"again|{code}")],
        [InlineKeyboardButton("👋 لا، إنهاء", callback_data="finish")]
    ])

WELCOME_TEXT = (
    "🌷 أهلًا بطالبتي المجتهدة\n\n"
    "سعيدة بوصولك إلى بنك أسئلة المهارات الرقمية 💻✨\n\n"
    "أحب أشوفك تجربين وتختبرين معلوماتك بنفسك 💚\n"
    "لا تخافين من الخطأ، فكل محاولة تساعدك تتعلمين أكثر وتتقنين مهاراتك.\n\n"
    "اختاري صفك الدراسي وابدئي المراجعة 🌟\n\n"
    "معلمتكِ رحاب الزهراني"
)

async def show_home(update):
    message = update.effective_message
    loc = location_grade(update)
    if loc is None:
        return  # صامت تمامًا خارج موضوع بنك الأسئلة
    if loc == "private":
        await message.reply_text(WELCOME_TEXT, reply_markup=grade_keyboard())
        return
    grade = CURRICULUM[loc][0]
    text = (
        "🌷 أهلًا بطالبتي المجتهدة\n\n"
        "سعيدة بوصولك إلى بنك أسئلة المهارات الرقمية 💻✨\n\n"
        "أحب أشوفك تجربين وتختبرين معلوماتك بنفسك 💚\n"
        "لا تخافين من الخطأ، فكل محاولة تساعدك تتعلمين أكثر وتتقنين مهاراتك.\n\n"
        f"🌟 أنتِ الآن في بنك أسئلة الصف {grade}\n"
        "اختاري الدرس الذي ترغبين في مراجعته 👇\n\n"
        "معلمتكِ رحاب الزهراني"
    )
    await message.reply_text(text, reply_markup=lesson_keyboard(loc))

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await show_home(update)

async def arabic_entry(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # أي رسالة نصية داخل موضوع بنك الأسئلة تفتح بنك الصف تلقائيًا.
    await show_home(update)

async def ids(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # يبقى /id متاحًا للتوثيق فقط داخل المواضيع المصرح بها أو في الخاص.
    if location_grade(update) is None:
        return
    m=update.effective_message
    await m.reply_text(f"chat_id: {update.effective_chat.id}\nmessage_thread_id: {getattr(m,'message_thread_id',None)}")

async def callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q=update.callback_query
    await q.answer()
    data=q.data
    loc = allowed_callback_grade(update)
    if loc is None:
        return  # لا استجابة خارج موضوع بنك الأسئلة
    if data=="noop":
        return
    if data=="home":
        if loc == "private":
            await q.edit_message_text("🎓 اختاري صفك الدراسي:", reply_markup=grade_keyboard())
        else:
            grade=CURRICULUM[loc][0]
            await q.edit_message_text(f"📚 اختاري درسًا من {grade}:", reply_markup=lesson_keyboard(loc))
        return
    if data.startswith("grade|"):
        code=data.split("|",1)[1]
        if loc != "private" and code != loc:
            return
        grade=CURRICULUM[code][0]
        context.user_data['grade']=code
        await q.edit_message_text(f"🌟 أهلًا بطالبة الصف {grade}\n\nاختاري الدرس الذي ترغبين في مراجعته:", reply_markup=lesson_keyboard(code))
        return
    if data.startswith("again|"):
        code=data.split("|",1)[1]
        if loc != "private" and code != loc:
            return
        grade=CURRICULUM[code][0]
        await q.edit_message_text(f"📚 رائع! اختاري درسًا آخر من {grade}:", reply_markup=lesson_keyboard(code))
        return
    if data=="finish":
        await q.edit_message_text(
            "🌟 أحسنتِ يا بطلة\n"
            "شكرًا لمشاركتك واجتهادك اليوم\n\n"
            "💚 أنا فخورة فيكِ وفي إنجازكِ\n"
            "استمري بهذا التميز ونلتقي في مراجعة جديدة بإذن الله 🌷\n\n"
            "معلمتكِ رحاب الزهراني"
        )
        return
    if data.startswith("lesson|"):
        _,code,ui,li=data.split("|")
        if loc != "private" and code != loc:
            return
        ui,li=int(ui),int(li)
        grade,units=CURRICULUM[code]
        unit,lessons=units[ui]
        lesson=lessons[li]
        await q.edit_message_text(
            f"🌟 اختيار جميل\n\n📘 {unit}\n📖 درس: {lesson}\n\n"
            "اقرئي السؤال جيدًا واختاري الإجابة الصحيحة. بالتوفيق 💚"
        )
        await send_lesson_quiz(update, context, code, unit, lesson)

async def send_lesson_quiz(update, context, code, unit, lesson):
    cq=update.callback_query
    msg=cq.message
    key=(code,unit,lesson)
    qs=list(QUESTION_BANK.get(key,[]))
    if not qs:
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            message_thread_id=getattr(msg,"message_thread_id",None),
            text=(f"📚 تم تجهيز درس «{lesson}» ضمن القائمة.\n"
                  "بنك أسئلة هذا الدرس لم يُدرج في الملف الحالي بعد، لذلك لن أعرض أسئلة غير موثقة من الكتاب."),
            reply_markup=after_keyboard(code)
        )
        return
    random.shuffle(qs)
    # 10 أسئلة في الجولة الواحدة حتى لا تصبح المحادثة طويلة، ويمكن العودة للدرس مرة أخرى لاحقًا.
    qs=qs[:min(10,len(qs))]
    for question, options, answer, explanation in qs:
        correct=options[answer]
        shuffled=list(options)
        random.shuffle(shuffled)
        correct_id=shuffled.index(correct)
        await context.bot.send_poll(
            chat_id=update.effective_chat.id,
            message_thread_id=getattr(msg,"message_thread_id",None),
            question=question,
            options=shuffled,
            type=PollType.QUIZ,
            correct_option_id=correct_id,
            explanation=explanation,
            is_anonymous=False
        )
    await context.bot.send_message(
        chat_id=update.effective_chat.id,
        message_thread_id=getattr(msg,"message_thread_id",None),
        text="🌟 انتهت أسئلة هذا الدرس. هل ترغبين في مراجعة درس آخر؟",
        reply_markup=after_keyboard(code)
    )

def main():
    logging.basicConfig(level=logging.INFO)
    app=Application.builder().token(TOKEN).build()
    app.add_handler(CommandHandler("start",start))
    app.add_handler(CommandHandler("id",ids))
    app.add_handler(CallbackQueryHandler(callback))
    # مداخل عربية سهلة: مراجعة، اسألني، بنك الأسئلة، ابدأ، أو أي رسالة عادية.
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, arabic_entry))
    print("DigitalSkillsRahabBot comprehensive navigation is running...")
    app.run_polling(allowed_updates=Update.ALL_TYPES)

if __name__=="__main__":
    main()
